/// <summary>
/// designed from AVA
/// </summary>
/// <param name="args">args</param>
[PostHandlerFor(classStr(SalesQuotationLineType), methodStr(SalesQuotationLineType, setStockedProduct))]
public static void SalesQuotationLineType_Post_setStockedProduct(XppPrePostArgs args)
{
    SalesQuotationLineType          salesQuotationLineType  = args.getThis();
    SalesQuotationLine              salesQuotationLine      = salesQuotationLineType.parmSalesQuotationLine();

    AVASalesParameters              avaSalesParameters = AVASalesParameters::find();

    if (avaSalesParameters.SalesQuotationNoStockedItem == NoYes::Yes)
    {
        salesQuotationLine.StockedProduct = NoYes::No;
    }


}
